<?php require_once __DIR__ . '/layout.php';
$id=(int)($_GET['id']??0); $requests=load_data('requests'); $request=$id ? (find_by_id($requests,$id) ?: []) : []; $request += ['user_id'=>'','reason_id'=>'','requested_at'=>date('Y-m-d\TH:i'),'description'=>'','it_employee'=>'','status'=>'new','result_comment'=>'']; if($request['requested_at']) $request['requested_at']=str_replace(' ','T',substr($request['requested_at'],0,16)); $users=users_all(); $reasons=reasons_all();
if($_SERVER['REQUEST_METHOD']==='POST'){ $item=['id'=>$id ?: next_id($requests),'user_id'=>(int)$_POST['user_id'],'reason_id'=>(int)$_POST['reason_id'],'requested_at'=>str_replace('T',' ',$_POST['requested_at']),'description'=>trim($_POST['description']),'it_employee'=>trim($_POST['it_employee']),'status'=>$_POST['status'],'result_comment'=>trim($_POST['result_comment']),'created_at'=>date('Y-m-d H:i:s')]; if($id){ foreach($requests as &$r) if((int)$r['id']===$id){$item['created_at']=$r['created_at']??$item['created_at']; $r=$item; break;} } else $requests[]=$item; save_data('requests',$requests); redirect('requests.php'); }
page_header($id?'Edit request':'Add request','requests'); ?><?php if(!$users): ?><div class="notice">First add at least one user.</div><?php endif; ?><div class="card"><h2><?= $id?'Edit request':'Add request' ?></h2><form method="post"><div class="form-grid"><div><label>User</label><select name="user_id" required><option value="">Select</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>" <?= ((int)$request['user_id']===(int)$u['id'])?'selected':'' ?>><?= h($u['full_name'].' — office '.$u['office']) ?></option><?php endforeach; ?></select></div><div><label>Reason</label><select name="reason_id" required><?php foreach($reasons as $r): ?><option value="<?= (int)$r['id'] ?>" <?= ((int)$request['reason_id']===(int)$r['id'])?'selected':'' ?>><?= h($r['name']) ?></option><?php endforeach; ?></select></div><div><label>Request date and time</label><input type="datetime-local" name="requested_at" required value="<?= h($request['requested_at']) ?>"></div><div><label>IT employee</label><input name="it_employee" value="<?= h($request['it_employee']) ?>"></div><div><label>Status</label><select name="status"><option value="new" <?= $request['status']==='new'?'selected':'' ?>>New</option><option value="progress" <?= $request['status']==='progress'?'selected':'' ?>>In progress</option><option value="done" <?= $request['status']==='done'?'selected':'' ?>>Done</option></select></div></div><div><label>Problem / request description</label><textarea name="description" required><?= h($request['description']) ?></textarea></div><div><label>Comment / resolution result</label><textarea name="result_comment"><?= h($request['result_comment']) ?></textarea></div><button class="btn">Save</button></form></div><?php page_footer(); ?>
